// SPDX-License-Identifier: PolyForm-Noncommercial-1.0.0
//! C ABI between the TreeDock engine and the desktop UI (MASTER_PLAN §3.5).
//!
//! Conventions:
//! * Sessions are opaque `u64` handles (0 = error; see [`td_last_error`]).
//! * Strings are UTF-16. Functions writing strings take `(buf, cap)` and
//!   return the full length needed, so callers can retry with a larger buffer.
//! * The UI pulls data a page at a time; progress is polled. No callbacks.
//! * Every entry point catches panics and reports them as errors.
//!
//! C# bindings are generated by `build.rs` (csbindgen) into the app project.
//!
//! # Safety
//!
//! Applies to every `unsafe extern "C"` function in this crate: pointer
//! arguments must be null or valid for the documented number of elements
//! (`cap`/`count`/`len`) for the duration of the call, and output structs must
//! be writable. Session handles are validated, so stale or invalid handles are
//! safe and simply produce an error.
#![allow(clippy::missing_safety_doc)]

use std::cell::RefCell;
use std::collections::HashMap;
use std::panic::{AssertUnwindSafe, catch_unwind};
use std::sync::atomic::{AtomicBool, AtomicU8, AtomicU64, AtomicUsize, Ordering};
use std::sync::{Arc, LazyLock, Mutex, RwLock};
use std::time::Instant;

use treedock_core::export::{self, ExportOptions};
use treedock_core::query::{self, SizeMeasure, SortKey};
use treedock_core::rows::FlatView;
use treedock_core::scan::{Progress, ScanControl, ScanError};
use treedock_core::treemap::{self, SunburstArc, TreemapOptions, TreemapRect};
use treedock_core::{NONE, NodeId, Tree, snapshot};
use treedock_ntfs::HardlinkPolicy;
use treedock_win::fileops::{self, Expected, OpItem, OpStatus};
use treedock_win::volume::{self, Media};
use treedock_win::{ScanMode, ScanOptions};

// ---------------------------------------------------------------- errors

thread_local! {
    static LAST_ERROR: RefCell<String> = const { RefCell::new(String::new()) };
}

fn set_error(e: impl Into<String>) {
    LAST_ERROR.with(|l| *l.borrow_mut() = e.into());
}

fn guard<T>(fallback: T, f: impl FnOnce() -> Result<T, String>) -> T {
    match catch_unwind(AssertUnwindSafe(f)) {
        Ok(Ok(v)) => v,
        Ok(Err(e)) => {
            set_error(e);
            fallback
        }
        Err(p) => {
            let msg = p
                .downcast_ref::<&str>()
                .map(|s| s.to_string())
                .or_else(|| p.downcast_ref::<String>().cloned())
                .unwrap_or_else(|| "unknown".into());
            set_error(format!("internal error: {msg}"));
            fallback
        }
    }
}

/// Copies `s` into `buf` (UTF-16, not NUL-terminated); returns the full length.
unsafe fn write_str_units(units: &[u16], buf: *mut u16, cap: u32) -> u32 {
    if !buf.is_null() && cap > 0 {
        let n = units.len().min(cap as usize);
        unsafe { std::ptr::copy_nonoverlapping(units.as_ptr(), buf, n) };
    }
    units.len() as u32
}

unsafe fn write_str(s: &str, buf: *mut u16, cap: u32) -> u32 {
    let units: Vec<u16> = s.encode_utf16().collect();
    unsafe { write_str_units(&units, buf, cap) }
}

unsafe fn read_str(p: *const u16, len: u32) -> Result<String, String> {
    if p.is_null() {
        return Err("null string".into());
    }
    let s = unsafe { std::slice::from_raw_parts(p, len as usize) };
    String::from_utf16(s).map_err(|_| "invalid UTF-16 string".into())
}

/// Writes the last error message for the calling thread.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_last_error(buf: *mut u16, cap: u32) -> u32 {
    let s = LAST_ERROR.with(|l| l.borrow().clone());
    unsafe { write_str(&s, buf, cap) }
}

#[unsafe(no_mangle)]
pub extern "C" fn td_abi_version() -> u32 {
    1
}

#[unsafe(no_mangle)]
pub extern "C" fn td_is_elevated() -> u32 {
    guard(0, || Ok(volume::is_elevated() as u32))
}

// ---------------------------------------------------------------- volumes

#[repr(C)]
pub struct TdVolume {
    pub root: [u16; 8],
    pub label: [u16; 64],
    pub filesystem: [u16; 16],
    pub total: u64,
    pub free: u64,
    pub cluster_size: u32,
    /// 2 removable, 3 fixed, 4 network, 5 optical, 6 ramdisk.
    pub drive_type: u32,
    /// 0 unknown, 1 ssd, 2 hdd, 3 removable, 4 network.
    pub media: u32,
    pub _pad: u32,
}

fn media_code(m: Option<Media>) -> u32 {
    match m {
        Some(Media::Ssd) => 1,
        Some(Media::Hdd) => 2,
        Some(Media::Removable) => 3,
        Some(Media::Network) => 4,
        _ => 0,
    }
}

fn fill<const N: usize>(dst: &mut [u16; N], s: &str) {
    *dst = [0; N];
    for (d, u) in dst.iter_mut().zip(s.encode_utf16().take(N - 1)) {
        *d = u;
    }
}

/// Fills up to `cap` volumes; returns the number available.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_volumes(out: *mut TdVolume, cap: u32) -> u32 {
    guard(0, || {
        let vols = volume::list_volumes();
        if !out.is_null() {
            for (i, v) in vols.iter().take(cap as usize).enumerate() {
                let d = unsafe { &mut *out.add(i) };
                fill(&mut d.root, &v.root);
                fill(&mut d.label, &v.label);
                fill(&mut d.filesystem, &v.filesystem);
                d.total = v.total;
                d.free = v.free;
                d.cluster_size = v.cluster_size;
                d.drive_type = v.drive_type;
                d.media = media_code(v.media);
                d._pad = 0;
            }
        }
        Ok(vols.len() as u32)
    })
}

// ---------------------------------------------------------------- sessions

pub const STATE_SCANNING: u8 = 1;
pub const STATE_DONE: u8 = 2;
pub const STATE_CANCELLED: u8 = 3;
pub const STATE_FAILED: u8 = 4;

pub const OP_IDLE: u8 = 0;
pub const OP_RUNNING: u8 = 1;
pub const OP_DONE: u8 = 2;

struct OpState {
    state: AtomicU8,
    total: AtomicUsize,
    done: AtomicUsize,
    ok: AtomicUsize,
    failed: AtomicUsize,
    skipped: AtomicUsize,
    cancel: AtomicBool,
    results: Mutex<Vec<(u8, String, String)>>,
}

impl Default for OpState {
    fn default() -> Self {
        OpState {
            state: AtomicU8::new(OP_IDLE),
            total: AtomicUsize::new(0),
            done: AtomicUsize::new(0),
            ok: AtomicUsize::new(0),
            failed: AtomicUsize::new(0),
            skipped: AtomicUsize::new(0),
            cancel: AtomicBool::new(false),
            results: Mutex::new(Vec::new()),
        }
    }
}

struct Session {
    tree: Arc<RwLock<Tree>>,
    control: Arc<ScanControl>,
    progress: Arc<Progress>,
    state: Arc<AtomicU8>,
    started: Instant,
    elapsed_ms: Arc<AtomicU64>,
    errors: Arc<Mutex<Vec<ScanError>>>,
    view: Mutex<Option<FlatView>>,
    /// Sorted children of one folder for the details list.
    list: Mutex<Vec<NodeId>>,
    op: Arc<OpState>,
}

static SESSIONS: LazyLock<Mutex<HashMap<u64, Arc<Session>>>> = LazyLock::new(|| Mutex::new(HashMap::new()));
static NEXT_ID: AtomicU64 = AtomicU64::new(1);

fn session(s: u64) -> Result<Arc<Session>, String> {
    SESSIONS.lock().unwrap().get(&s).cloned().ok_or_else(|| "invalid session".to_string())
}

fn register(sess: Session) -> u64 {
    let id = NEXT_ID.fetch_add(1, Ordering::Relaxed);
    SESSIONS.lock().unwrap().insert(id, Arc::new(sess));
    id
}

fn new_session(tree: Tree, state: u8) -> Session {
    Session {
        tree: Arc::new(RwLock::new(tree)),
        control: ScanControl::new(),
        progress: Progress::new(),
        state: Arc::new(AtomicU8::new(state)),
        started: Instant::now(),
        elapsed_ms: Arc::new(AtomicU64::new(0)),
        errors: Arc::new(Mutex::new(Vec::new())),
        view: Mutex::new(None),
        list: Mutex::new(Vec::new()),
        op: Arc::new(OpState::default()),
    }
}

#[repr(C)]
pub struct TdScanOptions {
    /// 0 auto, 1 walk, 2 mft.
    pub mode: u32,
    /// 0 once, 1 divide, 2 every.
    pub hardlinks: u32,
    /// 0 = automatic.
    pub threads: u32,
    /// 0 = detect, else as `TdVolume::media`.
    pub media: u32,
    pub low_impact: u32,
}

/// Starts scanning `path` on a background thread. Returns a session handle.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_scan_start(path: *const u16, len: u32, opts: *const TdScanOptions) -> u64 {
    guard(0, || {
        let path = unsafe { read_str(path, len)? };
        let o = unsafe { opts.as_ref() };
        let so = ScanOptions {
            mode: match o.map(|o| o.mode) {
                Some(1) => ScanMode::Walk,
                Some(2) => ScanMode::Mft,
                _ => ScanMode::Auto,
            },
            hardlinks: match o.map(|o| o.hardlinks) {
                Some(1) => HardlinkPolicy::Divide,
                Some(2) => HardlinkPolicy::Every,
                _ => HardlinkPolicy::Once,
            },
            threads: o.map(|o| o.threads as usize).filter(|&t| t > 0),
            media: match o.map(|o| o.media) {
                Some(1) => Some(Media::Ssd),
                Some(2) => Some(Media::Hdd),
                Some(3) => Some(Media::Removable),
                Some(4) => Some(Media::Network),
                _ => None,
            },
            low_impact: o.is_some_and(|o| o.low_impact != 0),
        };
        let setup = treedock_win::prepare(&path, &so)?;
        let sess = new_session(treedock_win::new_tree(&setup), STATE_SCANNING);
        let (tree, control, progress, state, elapsed, errors, started) = (
            sess.tree.clone(),
            sess.control.clone(),
            sess.progress.clone(),
            sess.state.clone(),
            sess.elapsed_ms.clone(),
            sess.errors.clone(),
            sess.started,
        );
        let id = register(sess);
        std::thread::Builder::new()
            .name("treedock-scan".into())
            .spawn(move || {
                let r = catch_unwind(AssertUnwindSafe(|| treedock_win::run(&setup, tree, control, progress)));
                elapsed.store(started.elapsed().as_millis() as u64, Ordering::Relaxed);
                match r {
                    Ok(out) => {
                        *errors.lock().unwrap() = out.errors;
                        state.store(if out.cancelled { STATE_CANCELLED } else { STATE_DONE }, Ordering::Release);
                    }
                    Err(_) => state.store(STATE_FAILED, Ordering::Release),
                }
            })
            .map_err(|e| e.to_string())?;
        Ok(id)
    })
}

/// Opens a saved `.tdsnap` snapshot as a finished session.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_snapshot_open(path: *const u16, len: u32) -> u64 {
    guard(0, || {
        let path = unsafe { read_str(path, len)? };
        let tree = snapshot::load(std::path::Path::new(&path)).map_err(|e| e.to_string())?;
        let sess = new_session(tree, STATE_DONE);
        sess.progress.done.store(true, Ordering::Release);
        Ok(register(sess))
    })
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_snapshot_save(s: u64, path: *const u16, len: u32) -> i32 {
    guard(-1, || {
        let sess = session(s)?;
        let path = unsafe { read_str(path, len)? };
        let t = sess.tree.read().unwrap();
        snapshot::save(&t, std::path::Path::new(&path)).map_err(|e| e.to_string())?;
        Ok(0)
    })
}

/// Releases a session (cancelling any running scan).
#[unsafe(no_mangle)]
pub extern "C" fn td_session_close(s: u64) {
    guard((), || {
        if let Some(sess) = SESSIONS.lock().unwrap().remove(&s) {
            sess.control.cancel();
            sess.op.cancel.store(true, Ordering::Relaxed);
        }
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn td_cancel(s: u64) {
    guard((), || {
        session(s)?.control.cancel();
        Ok(())
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn td_pause(s: u64, paused: u32) {
    guard((), || {
        let sess = session(s)?;
        if paused != 0 {
            sess.control.pause()
        } else {
            sess.control.resume()
        }
        Ok(())
    })
}

#[repr(C)]
pub struct TdProgress {
    /// STATE_* constant.
    pub state: u32,
    pub paused: u32,
    pub files: u64,
    pub dirs: u64,
    pub logical: u64,
    pub allocated: u64,
    pub errors: u64,
    pub elapsed_ms: u64,
    pub nodes: u64,
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_progress(s: u64, out: *mut TdProgress) -> i32 {
    guard(-1, || {
        let sess = session(s)?;
        let p = sess.progress.snapshot();
        let state = sess.state.load(Ordering::Acquire);
        let elapsed = if state == STATE_SCANNING {
            sess.started.elapsed().as_millis() as u64
        } else {
            sess.elapsed_ms.load(Ordering::Relaxed)
        };
        let nodes = sess.tree.try_read().map(|t| t.len() as u64).unwrap_or(0);
        let o = unsafe { out.as_mut().ok_or("null")? };
        *o = TdProgress {
            state: state as u32,
            paused: sess.control.is_paused() as u32,
            files: p.files,
            dirs: p.dirs,
            logical: p.logical,
            allocated: p.allocated,
            errors: p.errors,
            elapsed_ms: elapsed,
            nodes,
        };
        Ok(0)
    })
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_current_path(s: u64, buf: *mut u16, cap: u32) -> u32 {
    guard(0, || Ok(unsafe { write_str(&session(s)?.progress.snapshot().current, buf, cap) }))
}

#[unsafe(no_mangle)]
pub extern "C" fn td_error_count(s: u64) -> u32 {
    guard(0, || Ok(session(s)?.errors.lock().unwrap().len() as u32))
}

/// Writes "path\tmessage" for error `i`.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_error_at(s: u64, i: u32, buf: *mut u16, cap: u32) -> u32 {
    guard(0, || {
        let sess = session(s)?;
        let e = sess.errors.lock().unwrap();
        let e = e.get(i as usize).ok_or("index out of range")?;
        Ok(unsafe { write_str(&format!("{}\t{}", e.path, e.message.trim()), buf, cap) })
    })
}

#[repr(C)]
pub struct TdSummary {
    pub logical: u64,
    pub allocated: u64,
    pub files: u64,
    pub dirs: u64,
    pub errors: u32,
    pub pending: u32,
    pub cloud_files: u64,
    pub cloud_logical: u64,
    pub links_not_followed: u64,
    pub volume_total: u64,
    pub volume_free: u64,
    pub cluster_size: u32,
    pub complete: u32,
    pub elevated: u32,
    pub _pad: u32,
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_summary(s: u64, out: *mut TdSummary) -> i32 {
    guard(-1, || {
        let sess = session(s)?;
        let t = sess.tree.read().unwrap();
        let q = query::summary(&t, Tree::ROOT);
        let o = unsafe { out.as_mut().ok_or("null")? };
        *o = TdSummary {
            logical: q.logical,
            allocated: q.allocated,
            files: q.files,
            dirs: q.dirs,
            errors: q.errors,
            pending: q.pending,
            cloud_files: q.cloud_files,
            cloud_logical: q.cloud_logical,
            links_not_followed: q.links_not_followed,
            volume_total: t.meta.volume_total,
            volume_free: t.meta.volume_free,
            cluster_size: t.meta.cluster_size,
            complete: t.meta.complete as u32,
            elevated: t.meta.elevated as u32,
            _pad: 0,
        };
        Ok(0)
    })
}

/// Metadata strings: 0 root path, 1 scan mode, 2 filesystem, 3 volume label, 4 notes (newline-separated).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_meta_string(s: u64, which: u32, buf: *mut u16, cap: u32) -> u32 {
    guard(0, || {
        let sess = session(s)?;
        let t = sess.tree.read().unwrap();
        let m = &t.meta;
        let v = match which {
            0 => m.root_path.clone(),
            1 => m.scan_mode.clone(),
            2 => m.filesystem.clone(),
            3 => m.volume_label.clone(),
            4 => m.notes.join("\n"),
            _ => return Err("unknown field".into()),
        };
        Ok(unsafe { write_str(&v, buf, cap) })
    })
}

// ---------------------------------------------------------------- nodes

#[repr(C)]
pub struct TdNode {
    pub parent: u32,
    pub flags: u16,
    pub ext_id: u16,
    pub attrs: u32,
    pub is_dir: u8,
    pub exact: u8,
    pub has_children: u8,
    pub _pad: u8,
    pub logical: u64,
    pub allocated: u64,
    pub files: u64,
    pub dirs: u64,
    pub mtime: i64,
    pub ctime: i64,
}

fn node_info(t: &Tree, n: NodeId) -> TdNode {
    let st = t.dir_stats(n);
    TdNode {
        parent: t.parent(n),
        flags: t.flags(n),
        ext_id: t.ext_id(n),
        attrs: t.attrs(n),
        is_dir: t.is_dir(n) as u8,
        exact: t.is_exact(n) as u8,
        has_children: t.has_children(n) as u8,
        _pad: 0,
        logical: t.logical(n),
        allocated: t.allocated(n),
        files: st.map(|s| s.files).unwrap_or(0),
        dirs: st.map(|s| s.dirs).unwrap_or(0),
        mtime: t.mtime(n),
        ctime: t.ctime(n),
    }
}

fn check_node(t: &Tree, n: NodeId) -> Result<(), String> {
    if (n as usize) < t.len() { Ok(()) } else { Err("invalid node".into()) }
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_node(s: u64, node: u32, out: *mut TdNode) -> i32 {
    guard(-1, || {
        let sess = session(s)?;
        let t = sess.tree.read().unwrap();
        check_node(&t, node)?;
        unsafe { *out.as_mut().ok_or("null")? = node_info(&t, node) };
        Ok(0)
    })
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_node_name(s: u64, node: u32, buf: *mut u16, cap: u32) -> u32 {
    guard(0, || {
        let sess = session(s)?;
        let t = sess.tree.read().unwrap();
        check_node(&t, node)?;
        let mut v = Vec::new();
        t.name_utf16(node, &mut v);
        Ok(unsafe { write_str_units(&v, buf, cap) })
    })
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_node_path(s: u64, node: u32, buf: *mut u16, cap: u32) -> u32 {
    guard(0, || {
        let sess = session(s)?;
        let t = sess.tree.read().unwrap();
        check_node(&t, node)?;
        Ok(unsafe { write_str_units(&t.path_utf16(node), buf, cap) })
    })
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_ext_name(s: u64, ext_id: u16, buf: *mut u16, cap: u32) -> u32 {
    guard(0, || {
        let sess = session(s)?;
        let t = sess.tree.read().unwrap();
        Ok(unsafe { write_str(t.exts().name(ext_id), buf, cap) })
    })
}

// ---------------------------------------------------------------- tree-list view

pub const ROW_EXPANDED: u16 = 1;
pub const ROW_HAS_CHILDREN: u16 = 2;

#[repr(C)]
pub struct TdRow {
    pub node: u32,
    pub depth: u16,
    pub row_flags: u16,
    pub node_flags: u16,
    pub ext_id: u16,
    pub exact: u8,
    pub is_dir: u8,
    pub _pad: u16,
    pub logical: u64,
    pub allocated: u64,
    pub files: u64,
    pub dirs: u64,
    pub mtime: i64,
    /// Parent's allocated size (for percentage bars); 0 for the root row.
    pub parent_allocated: u64,
    pub parent_logical: u64,
}

fn sort_key(k: u32) -> SortKey {
    match k {
        0 => SortKey::Name,
        1 => SortKey::Logical,
        3 => SortKey::Files,
        4 => SortKey::Modified,
        5 => SortKey::Extension,
        _ => SortKey::Allocated,
    }
}

/// (Re)creates the session's tree-list view. Sort keys: 0 name, 1 size,
/// 2 allocated, 3 files, 4 modified, 5 extension. Returns the row count.
#[unsafe(no_mangle)]
pub extern "C" fn td_view_reset(s: u64, root: u32, sort: u32, descending: u32) -> u32 {
    guard(0, || {
        let sess = session(s)?;
        let t = sess.tree.read().unwrap();
        check_node(&t, root)?;
        let v = FlatView::new(&t, root, sort_key(sort), descending != 0);
        let n = v.len() as u32;
        *sess.view.lock().unwrap() = Some(v);
        Ok(n)
    })
}

fn with_view<R>(s: u64, f: impl FnOnce(&Tree, &mut FlatView) -> R) -> Result<R, String> {
    let sess = session(s)?;
    let t = sess.tree.read().unwrap();
    let mut v = sess.view.lock().unwrap();
    let v = v.as_mut().ok_or("view not created")?;
    Ok(f(&t, v))
}

#[unsafe(no_mangle)]
pub extern "C" fn td_view_len(s: u64) -> u32 {
    guard(0, || with_view(s, |_, v| v.len() as u32))
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_view_rows(s: u64, first: u32, count: u32, out: *mut TdRow) -> u32 {
    guard(0, || {
        if out.is_null() {
            return Err("null".into());
        }
        with_view(s, |t, v| {
            let mut n = 0u32;
            for i in first as usize..(first as usize + count as usize).min(v.len()) {
                let r = v.row(i).unwrap();
                unsafe { *out.add(n as usize) = make_row(t, r.node, r.depth, v.is_expanded(r.node)) };
                n += 1;
            }
            n
        })
    })
}

fn make_row(t: &Tree, node: NodeId, depth: u16, expanded: bool) -> TdRow {
    let p = t.parent(node);
    let info = node_info(t, node);
    let mut rf = 0u16;
    if expanded {
        rf |= ROW_EXPANDED;
    }
    if info.has_children != 0 {
        rf |= ROW_HAS_CHILDREN;
    }
    let has_parent = p != NONE && node != Tree::ROOT;
    TdRow {
        node,
        depth,
        row_flags: rf,
        node_flags: info.flags,
        ext_id: info.ext_id,
        exact: info.exact,
        is_dir: info.is_dir,
        _pad: 0,
        logical: info.logical,
        allocated: info.allocated,
        files: info.files,
        dirs: info.dirs,
        mtime: info.mtime,
        parent_allocated: if has_parent { t.allocated(p) } else { 0 },
        parent_logical: if has_parent { t.logical(p) } else { 0 },
    }
}

/// Expands or collapses row `row`; returns the new row count.
#[unsafe(no_mangle)]
pub extern "C" fn td_view_toggle(s: u64, row: u32) -> u32 {
    guard(0, || {
        with_view(s, |t, v| {
            v.toggle(t, row as usize);
            v.len() as u32
        })
    })
}

/// Rebuilds rows from current data (call periodically while scanning). Returns the row count.
#[unsafe(no_mangle)]
pub extern "C" fn td_view_refresh(s: u64) -> u32 {
    guard(0, || {
        with_view(s, |t, v| {
            v.rebuild(t);
            v.len() as u32
        })
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn td_view_sort(s: u64, sort: u32, descending: u32) -> u32 {
    guard(0, || {
        with_view(s, |t, v| {
            v.set_sort(t, sort_key(sort), descending != 0);
            v.len() as u32
        })
    })
}

/// Expands ancestors of `node`; returns its row index or -1.
#[unsafe(no_mangle)]
pub extern "C" fn td_view_reveal(s: u64, node: u32) -> i64 {
    guard(-1, || {
        with_view(
            s,
            |t, v| if (node as usize) < t.len() { v.reveal(t, node).map(|i| i as i64).unwrap_or(-1) } else { -1 },
        )
    })
}

// ---------------------------------------------------------------- details list

/// Loads the sorted children of `node` into the session's details list; returns the count.
#[unsafe(no_mangle)]
pub extern "C" fn td_list_reset(s: u64, node: u32, sort: u32, descending: u32) -> u32 {
    guard(0, || {
        let sess = session(s)?;
        let t = sess.tree.read().unwrap();
        check_node(&t, node)?;
        let mut v = query::sorted_children(&t, node, sort_key(sort), descending != 0);
        v.retain(|&c| t.flags(c) & treedock_core::tree::flags::DELETED == 0);
        let n = v.len() as u32;
        *sess.list.lock().unwrap() = v;
        Ok(n)
    })
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_list_rows(s: u64, first: u32, count: u32, out: *mut TdRow) -> u32 {
    guard(0, || {
        if out.is_null() {
            return Err("null".into());
        }
        let sess = session(s)?;
        let t = sess.tree.read().unwrap();
        let list = sess.list.lock().unwrap();
        let mut n = 0u32;
        for &node in list.iter().skip(first as usize).take(count as usize) {
            if (node as usize) < t.len() {
                unsafe { *out.add(n as usize) = make_row(&t, node, 0, false) };
                n += 1;
            }
        }
        Ok(n)
    })
}

/// Index of `node` in the details list, or -1.
#[unsafe(no_mangle)]
pub extern "C" fn td_list_index_of(s: u64, node: u32) -> i64 {
    guard(-1, || Ok(session(s)?.list.lock().unwrap().iter().position(|&n| n == node).map(|i| i as i64).unwrap_or(-1)))
}

/// 1 if the current user has full control of `path`, 0 if not, -1 on error.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_has_full_access(path: *const u16, len: u32) -> i32 {
    guard(-1, || {
        let p = unsafe { read_str(path, len)? };
        treedock_win::access::has_full_access(&p).map(|b| b as i32)
    })
}

/// Sunburst arcs for `root` (angles as fractions of a turn). Returns the count written.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_sunburst(
    s: u64,
    root: u32,
    max_depth: u32,
    min_sweep: f32,
    by_logical: u32,
    out: *mut SunburstArc,
    cap: u32,
) -> u32 {
    guard(0, || {
        let sess = session(s)?;
        let t = sess.tree.read().unwrap();
        check_node(&t, root)?;
        let m = if by_logical != 0 { SizeMeasure::Logical } else { SizeMeasure::Allocated };
        let arcs = treemap::sunburst(&t, root, max_depth.min(16) as u16, min_sweep.max(0.0), m, cap as usize);
        let n = arcs.len().min(cap as usize);
        if !out.is_null() {
            unsafe { std::ptr::copy_nonoverlapping(arcs.as_ptr(), out, n) };
        }
        Ok(n as u32)
    })
}

// ---------------------------------------------------------------- queries

/// Writes up to `n` node ids of the largest files under `root`; returns the count.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_top_files(s: u64, root: u32, n: u32, by_logical: u32, out: *mut u32) -> u32 {
    guard(0, || {
        let sess = session(s)?;
        let t = sess.tree.read().unwrap();
        check_node(&t, root)?;
        let m = if by_logical != 0 { SizeMeasure::Logical } else { SizeMeasure::Allocated };
        let v = query::top_files(&t, root, n as usize, m);
        if !out.is_null() {
            unsafe { std::ptr::copy_nonoverlapping(v.as_ptr(), out, v.len()) };
        }
        Ok(v.len() as u32)
    })
}

#[repr(C)]
pub struct TdExtStat {
    pub ext_id: u16,
    pub _pad: [u16; 3],
    pub files: u64,
    pub logical: u64,
    pub allocated: u64,
}

/// Per-extension totals under `root`, largest first. Returns the total number of extensions.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_ext_stats(s: u64, root: u32, out: *mut TdExtStat, cap: u32) -> u32 {
    guard(0, || {
        let sess = session(s)?;
        let t = sess.tree.read().unwrap();
        check_node(&t, root)?;
        let stats = query::ext_stats(&t, root);
        if !out.is_null() {
            for (i, e) in stats.iter().take(cap as usize).enumerate() {
                unsafe {
                    *out.add(i) = TdExtStat {
                        ext_id: t.exts().get(&e.ext).unwrap_or(0),
                        _pad: [0; 3],
                        files: e.files,
                        logical: e.logical,
                        allocated: e.allocated,
                    }
                };
            }
        }
        Ok(stats.len() as u32)
    })
}

#[repr(C)]
pub struct TdTreemapOptions {
    pub width: f32,
    pub height: f32,
    pub min_px: f32,
    pub padding: f32,
    pub header: f32,
    pub max_depth: u32,
    pub by_logical: u32,
}

/// Squarified treemap of `root`. Writes up to `cap` rectangles; returns the count written.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_treemap(
    s: u64,
    root: u32,
    opts: *const TdTreemapOptions,
    out: *mut TreemapRect,
    cap: u32,
) -> u32 {
    guard(0, || {
        let sess = session(s)?;
        let o = unsafe { opts.as_ref().ok_or("null")? };
        let t = sess.tree.read().unwrap();
        check_node(&t, root)?;
        let to = TreemapOptions {
            measure: if o.by_logical != 0 { SizeMeasure::Logical } else { SizeMeasure::Allocated },
            max_depth: o.max_depth.min(64) as u16,
            min_px: o.min_px.max(1.0),
            padding: o.padding.max(0.0),
            header: o.header.max(0.0),
            max_rects: cap as usize,
        };
        let rects = treemap::layout(&t, root, o.width, o.height, &to);
        let n = rects.len().min(cap as usize);
        if !out.is_null() {
            unsafe { std::ptr::copy_nonoverlapping(rects.as_ptr(), out, n) };
        }
        Ok(n as u32)
    })
}

// ---------------------------------------------------------------- export

/// Exports the tree. `format`: 0 CSV, 1 JSON. `max_depth` < 0 = unlimited.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_export(
    s: u64,
    path: *const u16,
    len: u32,
    format: u32,
    max_depth: i32,
    dirs_only: u32,
) -> i32 {
    guard(-1, || {
        let sess = session(s)?;
        let path = unsafe { read_str(path, len)? };
        let t = sess.tree.read().unwrap();
        let opts = ExportOptions {
            max_depth: (max_depth >= 0).then_some(max_depth as usize),
            include_files: dirs_only == 0,
            spreadsheet_safe: true,
            bom: format == 0,
        };
        let f = std::fs::File::create(&path).map_err(|e| format!("{path}: {e}"))?;
        let mut w = std::io::BufWriter::new(f);
        match format {
            0 => export::write_csv(&t, Tree::ROOT, &opts, &mut w),
            _ => export::write_json(&t, Tree::ROOT, &opts, &mut w),
        }
        .map_err(|e| e.to_string())?;
        Ok(0)
    })
}

// ---------------------------------------------------------------- file operations

/// Starts sending `nodes` to the Recycle Bin on a background thread. Items
/// are re-validated against the scan first; protected locations are refused.
/// Successfully recycled nodes are removed from the tree.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_recycle_start(s: u64, nodes: *const u32, count: u32, owner_hwnd: isize) -> i32 {
    guard(-1, || {
        let sess = session(s)?;
        if sess.state.load(Ordering::Acquire) == STATE_SCANNING {
            return Err("Wait for the scan to finish before deleting.".into());
        }
        if sess.op.state.load(Ordering::Acquire) == OP_RUNNING {
            return Err("Another operation is in progress.".into());
        }
        if nodes.is_null() || count == 0 {
            return Err("nothing selected".into());
        }
        let ids = unsafe { std::slice::from_raw_parts(nodes, count as usize) }.to_vec();
        let items: Vec<(NodeId, OpItem)> = {
            let t = sess.tree.read().unwrap();
            let mut v = Vec::new();
            for &n in &ids {
                check_node(&t, n)?;
                if n == Tree::ROOT {
                    return Err("The scan root cannot be deleted.".into());
                }
                v.push((
                    n,
                    OpItem {
                        path: t.path(n),
                        expected: Expected {
                            file_id: t.file_id(n),
                            logical: t.logical(n),
                            mtime: t.mtime(n),
                            is_dir: t.is_dir(n),
                        },
                    },
                ));
            }
            v
        };
        let op = sess.op.clone();
        *op.results.lock().unwrap() = Vec::new();
        op.total.store(items.len(), Ordering::Relaxed);
        for c in [&op.done, &op.ok, &op.failed, &op.skipped] {
            c.store(0, Ordering::Relaxed);
        }
        op.cancel.store(false, Ordering::Relaxed);
        op.state.store(OP_RUNNING, Ordering::Release);
        let tree = sess.tree.clone();
        std::thread::Builder::new()
            .name("treedock-recycle".into())
            .spawn(move || {
                let plain: Vec<OpItem> = items.iter().map(|(_, i)| i.clone()).collect();
                let _ = catch_unwind(AssertUnwindSafe(|| {
                    fileops::recycle(&plain, owner_hwnd, &op.cancel, |i, r| {
                        let code = match r.status {
                            OpStatus::Done => {
                                op.ok.fetch_add(1, Ordering::Relaxed);
                                tree.write().unwrap().remove(items[i].0);
                                0
                            }
                            OpStatus::Skipped => {
                                op.skipped.fetch_add(1, Ordering::Relaxed);
                                1
                            }
                            OpStatus::Failed => {
                                op.failed.fetch_add(1, Ordering::Relaxed);
                                2
                            }
                            OpStatus::Cancelled => 3,
                        };
                        op.results.lock().unwrap().push((code, r.path.clone(), r.message.clone()));
                        op.done.fetch_add(1, Ordering::Relaxed);
                    });
                }));
                op.state.store(OP_DONE, Ordering::Release);
            })
            .map_err(|e| e.to_string())?;
        Ok(0)
    })
}

#[repr(C)]
pub struct TdOpProgress {
    /// OP_* constant.
    pub state: u32,
    pub total: u32,
    pub done: u32,
    pub ok: u32,
    pub failed: u32,
    pub skipped: u32,
}

#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_op_progress(s: u64, out: *mut TdOpProgress) -> i32 {
    guard(-1, || {
        let op = session(s)?.op.clone();
        unsafe {
            *out.as_mut().ok_or("null")? = TdOpProgress {
                state: op.state.load(Ordering::Acquire) as u32,
                total: op.total.load(Ordering::Relaxed) as u32,
                done: op.done.load(Ordering::Relaxed) as u32,
                ok: op.ok.load(Ordering::Relaxed) as u32,
                failed: op.failed.load(Ordering::Relaxed) as u32,
                skipped: op.skipped.load(Ordering::Relaxed) as u32,
            }
        };
        Ok(0)
    })
}

#[unsafe(no_mangle)]
pub extern "C" fn td_op_cancel(s: u64) {
    guard((), || {
        session(s)?.op.cancel.store(true, Ordering::Relaxed);
        Ok(())
    })
}

/// Result `i` as "status\tpath\tmessage" (status: 0 done, 1 skipped, 2 failed, 3 cancelled).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_op_result(s: u64, i: u32, buf: *mut u16, cap: u32) -> u32 {
    guard(0, || {
        let op = session(s)?.op.clone();
        let r = op.results.lock().unwrap();
        let (c, p, m) = r.get(i as usize).ok_or("index out of range")?;
        Ok(unsafe { write_str(&format!("{c}\t{p}\t{m}"), buf, cap) })
    })
}

/// Checks whether a path is protected from deletion; writes the reason and returns its length (0 = not protected).
#[unsafe(no_mangle)]
pub unsafe extern "C" fn td_protected_reason(path: *const u16, len: u32, buf: *mut u16, cap: u32) -> u32 {
    guard(0, || {
        let p = unsafe { read_str(path, len)? };
        Ok(match fileops::protected_reason(&p) {
            Some(r) => unsafe { write_str(&r, buf, cap) },
            None => 0,
        })
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    fn wide(s: &str) -> Vec<u16> {
        s.encode_utf16().collect()
    }

    fn string(f: impl Fn(*mut u16, u32) -> u32) -> String {
        let n = f(std::ptr::null_mut(), 0);
        let mut b = vec![0u16; n as usize];
        f(b.as_mut_ptr(), n);
        String::from_utf16(&b).unwrap()
    }

    #[test]
    fn scan_session_end_to_end() {
        let d = std::env::temp_dir().join(format!("treedock-ffi-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&d);
        std::fs::create_dir_all(d.join("sub")).unwrap();
        std::fs::write(d.join("sub\\big.bin"), vec![0u8; 50_000]).unwrap();
        std::fs::write(d.join("small.txt"), b"hi").unwrap();
        let p = wide(d.to_str().unwrap());
        let s = unsafe { td_scan_start(p.as_ptr(), p.len() as u32, std::ptr::null()) };
        assert_ne!(s, 0, "{}", string(|b, c| unsafe { td_last_error(b, c) }));
        let mut prog: TdProgress = unsafe { std::mem::zeroed() };
        for _ in 0..500 {
            unsafe { td_progress(s, &mut prog) };
            if prog.state != STATE_SCANNING as u32 {
                break;
            }
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
        assert_eq!(prog.state, STATE_DONE as u32);
        let mut sum: TdSummary = unsafe { std::mem::zeroed() };
        unsafe { td_summary(s, &mut sum) };
        assert_eq!((sum.files, sum.dirs, sum.logical), (2, 1, 50_002));

        assert_eq!(td_view_reset(s, 0, 2, 1), 3);
        let mut rows: Vec<TdRow> = (0..3).map(|_| unsafe { std::mem::zeroed() }).collect();
        assert_eq!(unsafe { td_view_rows(s, 0, 10, rows.as_mut_ptr()) }, 3);
        assert_eq!(rows[1].is_dir, 1);
        assert_eq!(string(|b, c| unsafe { td_node_name(s, rows[1].node, b, c) }), "sub");
        assert_eq!(td_view_toggle(s, 1), 4);
        assert_eq!(td_view_sort(s, 0, 0), 4);

        assert_eq!(td_list_reset(s, 0, 2, 1), 2);
        let mut lrows: Vec<TdRow> = (0..2).map(|_| unsafe { std::mem::zeroed() }).collect();
        assert_eq!(unsafe { td_list_rows(s, 0, 10, lrows.as_mut_ptr()) }, 2);
        assert_eq!(string(|b, c| unsafe { td_node_name(s, lrows[0].node, b, c) }), "sub");
        assert_eq!(lrows[0].parent_allocated, sum.allocated);
        assert_eq!(td_list_index_of(s, lrows[1].node), 1);
        let mut arcs =
            vec![SunburstArc { node: 0, depth: 0, flags: 0, _pad: 0, ext: 0, _pad2: 0, start: 0.0, sweep: 0.0 }; 16];
        assert!(unsafe { td_sunburst(s, 0, 4, 0.0, 0, arcs.as_mut_ptr(), 16) } >= 2);
        assert_eq!(unsafe { td_has_full_access(p.as_ptr(), p.len() as u32) }, 1);

        let mut top = [0u32; 4];
        assert_eq!(unsafe { td_top_files(s, 0, 4, 0, top.as_mut_ptr()) }, 2);
        assert!(string(|b, c| unsafe { td_node_path(s, top[0], b, c) }).ends_with("sub\\big.bin"));
        let mut ext: Vec<TdExtStat> = (0..4).map(|_| unsafe { std::mem::zeroed() }).collect();
        assert_eq!(unsafe { td_ext_stats(s, 0, ext.as_mut_ptr(), 4) }, 2);
        assert_eq!(string(|b, c| unsafe { td_ext_name(s, ext[0].ext_id, b, c) }), "bin");

        let o = TdTreemapOptions {
            width: 400.0,
            height: 300.0,
            min_px: 2.0,
            padding: 1.0,
            header: 0.0,
            max_depth: 8,
            by_logical: 0,
        };
        let mut rects =
            vec![
                TreemapRect { x: 0.0, y: 0.0, w: 0.0, h: 0.0, node: 0, depth: 0, flags: 0, _pad: 0, ext: 0, _pad2: 0 };
                64
            ];
        assert!(unsafe { td_treemap(s, 0, &o, rects.as_mut_ptr(), 64) } >= 2);

        let snap = wide(d.join("x.tdsnap").to_str().unwrap());
        assert_eq!(unsafe { td_snapshot_save(s, snap.as_ptr(), snap.len() as u32) }, 0);
        let s2 = unsafe { td_snapshot_open(snap.as_ptr(), snap.len() as u32) };
        assert_ne!(s2, 0);
        let mut sum2: TdSummary = unsafe { std::mem::zeroed() };
        unsafe { td_summary(s2, &mut sum2) };
        assert_eq!(sum2.logical, 50_002);

        let csv = wide(d.join("x.csv").to_str().unwrap());
        assert_eq!(unsafe { td_export(s, csv.as_ptr(), csv.len() as u32, 0, -1, 0) }, 0);
        assert!(std::fs::read_to_string(d.join("x.csv")).unwrap().contains("big.bin"));

        // Root cannot be recycled; invalid sessions report errors.
        let root = [0u32];
        assert_eq!(unsafe { td_recycle_start(s, root.as_ptr(), 1, 0) }, -1);
        assert!(string(|b, c| unsafe { td_last_error(b, c) }).contains("root"));
        assert_eq!(td_view_len(999_999), 0);
        assert!(string(|b, c| unsafe { td_last_error(b, c) }).contains("invalid session"));

        td_session_close(s);
        td_session_close(s2);
        let _ = std::fs::remove_dir_all(&d);
    }

    #[test]
    fn volumes_and_errors() {
        let n = unsafe { td_volumes(std::ptr::null_mut(), 0) };
        assert!(n > 0);
        let mut v: Vec<TdVolume> = (0..n).map(|_| unsafe { std::mem::zeroed() }).collect();
        assert_eq!(unsafe { td_volumes(v.as_mut_ptr(), n) }, n);
        assert!(v[0].total > 0);
        let bad = wide("Z:\\definitely\\missing\\treedock");
        assert_eq!(unsafe { td_scan_start(bad.as_ptr(), bad.len() as u32, std::ptr::null()) }, 0);
        assert_eq!(td_abi_version(), 1);
    }
}
